set
  title = 'Study Abroad / Immersion',
  goal = 'Study Abroad / Immersion',
  summary = 'Students learn to turn immersion into rigorous language growth, intercultural competence, ethical community engagement, local research, and reflective academic synthesis.',
  data = $sabijson${"slug": "study-abroad-immersion", "title": "Study Abroad / Immersion", "description": "Students learn to turn immersion into rigorous language growth, intercultural competence, ethical community engagement, local research, and reflective academic synthesis.", "topics": [{"id": "1a1bcfed-3e64-4f97-8461-0ec54f6f8dcc", "type": "topic", "title": "Pre-Departure Cultural Preparation", "description": "Prepares students to enter a host community with historical context, humility, practical readiness, and an informed sense of local norms.", "children": [{"id": "8c82cf26-1e20-4854-b95e-5a4e05e56262", "type": "subtopic", "title": "Host-country context", "children": [{"id": "8ff66353-de70-41ac-9b4d-2940f657f6b2", "type": "concept", "title": "Political geography and regional diversity"}, {"id": "ddf372db-cadf-4b79-b3e5-a62a7ddff6fd", "type": "concept", "title": "Recent history, social debates, and local institutions"}, {"id": "1ad74866-ceb2-49e3-ac06-e351a61e5436", "type": "concept", "title": "Urban/rural distinctions, class, race, gender, and religion"}], "description": "Students begin with enough historical and social context to avoid treating immersion as tourism."}, {"id": "0fb71f97-0b89-4ea2-98d7-50b8f32e3f9c", "type": "subtopic", "title": "Practical readiness", "children": [{"id": "8cbb75ff-2cfc-41a2-84bc-64ee48c5af51", "type": "concept", "title": "Passports, visas, insurance, money, phones, and transport"}, {"id": "415a37bf-d122-4ab7-aa58-68efb1f1591f", "type": "concept", "title": "Packing, medication planning, accessibility, and emergency contacts"}, {"id": "411493d5-4cc2-41dc-ab69-424ba441773e", "type": "concept", "title": "Host-university calendars, grading, and course registration"}], "description": "Preparation turns logistics into academic readiness and reduces avoidable stress abroad."}, {"id": "c624f209-912f-4a3e-8b26-141cb09ef72f", "type": "subtopic", "title": "Cultural humility", "children": [{"id": "16e880c1-921b-47c4-9636-43b8e816e05d", "type": "concept", "title": "Stereotype checks and expectation mapping"}, {"id": "f3a788af-84f4-4fe7-92e7-8957c607903c", "type": "concept", "title": "Observer role versus participant role"}, {"id": "76f3675d-d145-4aca-bf87-f23d4573b492", "type": "concept", "title": "Respect, curiosity, and asking better questions"}], "description": "Students learn to enter unfamiliar settings as listeners and learners, not instant experts."}]}, {"id": "c7c285cf-05c4-4d7c-813c-ca7c98fa5a26", "type": "topic", "title": "Personal Language Goals and Immersion Plan", "description": "Turns immersion into a deliberate learning project with goals for speaking, listening, reading, writing, vocabulary, and feedback.", "children": [{"id": "1b6ad74d-3840-4f36-bb7b-e825dea1ddd5", "type": "subtopic", "title": "Proficiency self-assessment", "children": [{"id": "02faee6c-33b6-467a-9827-6c143a2e169c", "type": "concept", "title": "ACTFL-style can-do statements"}, {"id": "3b7c796b-70e2-43f4-b42d-919b8ef730d3", "type": "concept", "title": "Speaking, listening, reading, writing, and mediation"}, {"id": "cee85246-8639-4ec4-9cd9-beff797c14de", "type": "concept", "title": "Baseline recording or writing sample"}], "description": "Students identify current strengths and gaps so immersion goals are measurable."}, {"id": "4db5c12c-fc8d-4d7b-a219-b6f81dce05e0", "type": "subtopic", "title": "Daily language routines", "children": [{"id": "d1c48bfa-e8d5-4f8b-8474-5fd8c489dfd8", "type": "concept", "title": "Conversation targets and weekly challenges"}, {"id": "c1822882-8d81-437a-a642-f21fb9a1075b", "type": "concept", "title": "Media diet, reading logs, and vocabulary capture"}, {"id": "a77f7763-f51e-4d74-b8e7-19d08b281d16", "type": "concept", "title": "Office hours, tutoring, intercambio, and peer feedback"}], "description": "Students design habits that make Spanish the default medium for ordinary life."}, {"id": "a4e76178-e76a-4209-8574-fc15723ead0c", "type": "subtopic", "title": "Feedback and repair", "children": [{"id": "6bfc8dad-a8ce-4f27-9ad2-6f97ab82c8a3", "type": "concept", "title": "Clarification questions"}, {"id": "ae65dec8-41da-400e-adf2-e3d02353eb65", "type": "concept", "title": "Circumlocution and paraphrase"}, {"id": "a1ba1686-7a11-4059-a1f5-c36239fcbd01", "type": "concept", "title": "Tracking repeated errors and new phrases"}], "description": "Students learn to welcome correction, negotiate meaning, and recover from breakdowns."}]}, {"id": "825592f4-5257-4ab6-8bbf-1cbdee24817d", "type": "topic", "title": "Intercultural Communication and Pragmatics", "description": "Builds awareness of register, politeness, nonverbal cues, repair strategies, humor, disagreement, and culturally situated interaction.", "children": [{"id": "06f8df77-cd88-4fad-9b15-b590686073a3", "type": "subtopic", "title": "Register and politeness", "children": [{"id": "a2b56856-94c9-4740-904e-e479ced1f4c4", "type": "concept", "title": "Tu, usted, vos, and forms of address"}, {"id": "a03cd2e5-c6e9-4e64-aea7-d9cf067d085f", "type": "concept", "title": "Greetings, leave-taking, thanks, apologies, and requests"}, {"id": "51108836-63bc-407e-804a-58e03147f8ad", "type": "concept", "title": "Directness, indirectness, and softening strategies"}], "description": "The goal is to understand how grammar choices create social meaning."}, {"id": "5da0f026-c940-450f-ad14-357bd45196c0", "type": "subtopic", "title": "Nonverbal and interactional norms", "children": [{"id": "c6e5a0e3-bbf3-4794-9f04-753b8ab722ed", "type": "concept", "title": "Personal space and eye contact"}, {"id": "3adf4253-08d1-41f3-a91f-20dd53b160f3", "type": "concept", "title": "Interruptions, overlap, pacing, and backchanneling"}, {"id": "19d1e12e-63d6-4d7e-beae-52856bd5682e", "type": "concept", "title": "Humor, irony, teasing, and taboo topics"}], "description": "Students learn that communication includes timing, space, gesture, silence, and turn-taking."}, {"id": "f7bd9912-0b02-4482-a704-b1ecb4544bd5", "type": "subtopic", "title": "Conflict and repair", "children": [{"id": "08c0a6aa-ebf4-4919-8563-4753d6bf9971", "type": "concept", "title": "Misunderstanding repair"}, {"id": "9b81a651-aed1-48b8-9bb7-9748555ff412", "type": "concept", "title": "Disagreement without escalation"}, {"id": "69ca6c73-2130-4490-bed5-6e75724976dc", "type": "concept", "title": "Apologizing, explaining intent, and learning from friction"}], "description": "Immersion includes mistakes, so students practice ethical and resilient communication."}]}, {"id": "9ae19e01-b314-4f9e-aa81-5cd57b260bc8", "type": "topic", "title": "Academic Coursework in the Host Context", "description": "Helps students navigate host-university expectations, academic genres, classroom participation, citation practices, and faculty relationships.", "children": [{"id": "5014c54a-10c9-47dc-9386-81aa6e24b4fe", "type": "subtopic", "title": "Host-university expectations", "children": [{"id": "1f9463c5-6c91-4a58-9755-901a359b9357", "type": "concept", "title": "Lecture, seminar, lab, and tutorial norms"}, {"id": "57972b05-c60e-46cb-ab34-8757f0e21ffa", "type": "concept", "title": "Participation styles and professor communication"}, {"id": "b601e501-645d-40e7-9be0-a568e4cfff35", "type": "concept", "title": "Attendance, deadlines, grading, and exam formats"}], "description": "Students learn how academic culture may differ from their home institution."}, {"id": "f26fbc72-6fed-4ff0-bd7a-b306d1d91ec3", "type": "subtopic", "title": "Academic Spanish", "children": [{"id": "4278e3ad-dc8e-4120-b01b-413fa5aedd02", "type": "concept", "title": "Note-taking, summaries, abstracts, and presentations"}, {"id": "7a3c167a-1e23-4f52-ab00-64f85fcf0a1b", "type": "concept", "title": "Discipline-specific vocabulary"}, {"id": "56830b2f-9fd3-4c51-9945-9b84f3e417a2", "type": "concept", "title": "Office-hour scripts and email etiquette"}], "description": "This subtopic helps students perform in advanced disciplinary settings."}, {"id": "cf02f166-f091-403f-bba4-a91c2d02c666", "type": "subtopic", "title": "Integrity and citation", "children": [{"id": "71fe9a3d-80f3-4754-9da8-0721075e9f3d", "type": "concept", "title": "Citation styles and plagiarism standards"}, {"id": "6625d3a4-3a4d-4522-9e0c-3739029474b5", "type": "concept", "title": "Collaborative work norms"}, {"id": "4c061045-1c32-4a46-bd8d-28fef437fe1e", "type": "concept", "title": "Using translation tools responsibly"}], "description": "Students adapt to local expectations while maintaining strong academic ethics."}]}, {"id": "05701dce-a9d5-49f1-899a-1122ee0d2696", "type": "topic", "title": "Housing, Homestay, and Everyday Life", "description": "Treats daily routines, household norms, transportation, meals, money, and time as key sites of language and cultural learning.", "children": [{"id": "4f99ea45-c37b-47fd-91fc-2d022c1c4ddb", "type": "subtopic", "title": "Household communication", "children": [{"id": "14c07788-3208-40f9-93d8-c062e27467a8", "type": "concept", "title": "Meal routines, chores, guests, privacy, and quiet hours"}, {"id": "e14c8066-6805-4016-ba99-5cebe036ef28", "type": "concept", "title": "Clarifying expectations respectfully"}, {"id": "2a97b791-ff75-4f7e-b9f8-af268c7463c0", "type": "concept", "title": "Conversation with host families or roommates"}], "description": "Students learn to make daily life a serious site of language development."}, {"id": "1f58dce3-94c7-4443-b3b8-cb0c22cbd6a1", "type": "subtopic", "title": "Local navigation", "children": [{"id": "63473a3c-7632-46e3-8702-8f92ffc1ec3d", "type": "concept", "title": "Public transportation and walking routes"}, {"id": "e1e75beb-e335-4de1-83b9-ef3a5adde38b", "type": "concept", "title": "Shopping, markets, pharmacies, banks, and appointments"}, {"id": "65aa1ca4-29a8-4b39-a36d-d155e1b91dd4", "type": "concept", "title": "Asking for directions, solving problems, and reading signage"}], "description": "This subtopic builds independence and confidence in ordinary civic life."}, {"id": "582a63c0-402c-4536-9af6-ff7a7dadff74", "type": "subtopic", "title": "Time, money, and routines", "children": [{"id": "3d9983b8-48a6-411e-a9cf-7bdac880c50c", "type": "concept", "title": "Punctuality, scheduling, and bureaucracy"}, {"id": "349a8ede-ff8e-4018-9418-85b321d3536a", "type": "concept", "title": "Cash, cards, tipping, receipts, and budgeting"}, {"id": "a1efc2f2-95db-4353-979d-bafe9259b009", "type": "concept", "title": "Leisure, rest, religious calendars, and public holidays"}], "description": "Students compare practical norms without turning difference into judgment."}]}, {"id": "2986772e-4af6-40cc-ba23-c6a6047eb7c6", "type": "topic", "title": "Community Engagement and Ethical Participation", "description": "Frames community involvement through reciprocity, consent, local expertise, power, service ethics, and sustained accountability.", "children": [{"id": "d60b5ec9-5764-48d9-87b8-5297ef82190e", "type": "subtopic", "title": "Reciprocity and local expertise", "children": [{"id": "7103918e-9d67-4a9f-a3a5-04d50a715fb1", "type": "concept", "title": "Community partners and host expectations"}, {"id": "ffc4293f-c719-4efe-8659-b2d5ad9866a1", "type": "concept", "title": "Listening before proposing"}, {"id": "35e929c8-c7c2-4e91-856c-4f7b7f9bc264", "type": "concept", "title": "Avoiding savior narratives and extractive service"}], "description": "Students learn that community engagement should benefit from local priorities and knowledge."}, {"id": "330dfd3b-b338-4ccd-86bf-3b5071eb504c", "type": "subtopic", "title": "Volunteer and service ethics", "children": [{"id": "ed9e9a95-fa86-4934-8110-fcc59d49f1a3", "type": "concept", "title": "Consent, confidentiality, and role clarity"}, {"id": "37e3b889-6bee-42f7-87a3-10fcc6387f9e", "type": "concept", "title": "Continuity, reliability, and scope of competence"}, {"id": "945936d8-e17e-4f2b-9bcd-2a30fa33f7d0", "type": "concept", "title": "Documenting contributions without self-promotion"}], "description": "This section helps students participate responsibly in schools, NGOs, clinics, cultural centers, or neighborhood projects."}, {"id": "1e927f45-5e81-40b8-a17d-cf785fa5ea00", "type": "subtopic", "title": "Public participation", "children": [{"id": "94f88efa-3786-4544-bdc3-eb983ea3a262", "type": "concept", "title": "Local events, meetings, workshops, and festivals"}, {"id": "dca18b60-3185-48a1-9f1f-8c4e14090a56", "type": "concept", "title": "Appropriate photography and social media"}, {"id": "7cf8f010-f53a-4a30-a77c-bb186e21558c", "type": "concept", "title": "Dress, speech, and behavior in community settings"}], "description": "Students practice being respectful participants in civic and cultural life."}]}, {"id": "967d9248-3162-43d1-9ba1-86f95b3e26bd", "type": "topic", "title": "Local History and Cultural Institutions", "description": "Uses museums, archives, neighborhoods, monuments, festivals, theaters, libraries, and public spaces as living classrooms.", "children": [{"id": "a2e6d469-2e6a-4152-8df0-f38f8981d2c4", "type": "subtopic", "title": "Museums, archives, and libraries", "children": [{"id": "dd5a9224-47ba-461f-a878-bbc6f35d99fb", "type": "concept", "title": "Museum labels and curatorial choices"}, {"id": "11e148aa-f29f-4472-9d7a-53cd9c7cde3c", "type": "concept", "title": "Archives, newspapers, maps, and oral-history collections"}, {"id": "190dc05f-33fa-440e-9f44-2207befac983", "type": "concept", "title": "National, regional, municipal, and community institutions"}], "description": "Students use institutions to connect course themes to local memory and knowledge."}, {"id": "b7782a96-f2d6-41de-8037-e6e43cab6d44", "type": "subtopic", "title": "Neighborhoods and public space", "children": [{"id": "8d50940c-ac38-4910-8c80-4c786f10f894", "type": "concept", "title": "Plazas, markets, monuments, transit, walls, and street art"}, {"id": "66b24871-0214-454f-9659-3c416a1f3006", "type": "concept", "title": "Gentrification, tourism, inequality, and urban change"}, {"id": "57bcc49a-193d-4052-86a8-c1288d0e9474", "type": "concept", "title": "Sacred spaces, campuses, and civic buildings"}], "description": "Students learn to read the built environment as cultural evidence."}, {"id": "774ca857-6e1b-4eba-88c5-065edd109882", "type": "subtopic", "title": "Cultural programming", "children": [{"id": "ecc6141b-0912-490b-b017-8e74d52f1021", "type": "concept", "title": "Theater, film, concerts, lectures, and exhibitions"}, {"id": "374f1c12-75be-40b3-8053-c0c69caada7d", "type": "concept", "title": "Festivals, commemorations, and public rituals"}, {"id": "6120df48-f1cb-4eb8-8d4d-ce994cad54f7", "type": "concept", "title": "Event reviews and cultural interpretation"}], "description": "Students practice sustained engagement with local artistic and intellectual life."}]}, {"id": "2a1e92b6-78fb-4411-bc8f-f3665e8c3217", "type": "topic", "title": "Dialect, Regional Vocabulary, and Sociolinguistic Variation", "description": "Teaches students to document regional Spanish, speech communities, accents, slang, code-switching, and language attitudes.", "children": [{"id": "efc9ea8f-8290-4a40-bb1f-49c3f684085b", "type": "subtopic", "title": "Sound and accent awareness", "children": [{"id": "9d52e959-3725-4328-ba91-65cc4e483cc7", "type": "concept", "title": "Seseo, ceceo, yeismo, aspiration, rhythm, and intonation"}, {"id": "f8a6a723-fda8-42f9-9ec8-b12f2317f418", "type": "concept", "title": "Regional pronunciation patterns"}, {"id": "c7f62bb0-495e-49da-b49d-1e3d81ebe7ef", "type": "concept", "title": "Listening logs and transcription practice"}], "description": "Students learn to listen analytically without ranking dialects as better or worse."}, {"id": "885992b0-a49b-48b3-93cc-87e770088769", "type": "subtopic", "title": "Lexicon and idiom", "children": [{"id": "89239837-1861-4b0b-bc26-5f5dca49194c", "type": "concept", "title": "Local terms for food, transport, school, work, and social life"}, {"id": "1845c319-4e5a-4715-81ca-420249b86e39", "type": "concept", "title": "Slang, idioms, taboo terms, and euphemisms"}, {"id": "833bfba4-3435-414f-b9ce-569fa6cfae3d", "type": "concept", "title": "False friends and pragmatic force"}], "description": "Immersion expands vocabulary through real contexts rather than word lists alone."}, {"id": "159587c6-d07d-4bc6-bd2a-02c6403d4dc8", "type": "subtopic", "title": "Language contact and identity", "children": [{"id": "d87de698-c3ca-4d3b-abfa-71d4316a41bf", "type": "concept", "title": "Code-switching and translanguaging"}, {"id": "4545cce0-789e-47b6-b472-17f68e82d5c7", "type": "concept", "title": "Indigenous, regional, and immigrant languages"}, {"id": "d343b511-3101-4bf8-8bb2-ce4a34fd9da2", "type": "concept", "title": "Language prestige, stigma, and language policy"}], "description": "Students connect Spanish variation to migration, Indigenous languages, bilingualism, and class."}]}, {"id": "3089a610-2cdd-4f30-817f-0a4b5992ab53", "type": "topic", "title": "Wellbeing, Safety, Identity, and Responsible Travel", "description": "Makes health, risk assessment, identity navigation, accessibility, digital security, and support systems part of academic preparation.", "children": [{"id": "8599d43a-b8b1-4306-85e7-6c8aa926ce99", "type": "subtopic", "title": "Health and support systems", "children": [{"id": "d568054f-5592-46f0-a401-18b8b5441cd7", "type": "concept", "title": "Mental health, stress, sleep, nutrition, and exercise"}, {"id": "f0bc3d90-3e6c-45af-b95f-77c0348ef7db", "type": "concept", "title": "Clinics, pharmacies, insurance, and emergency services"}, {"id": "296d497e-ab68-464f-9aba-133bb843cee6", "type": "concept", "title": "Support contacts, reporting structures, and crisis plans"}], "description": "Students prepare to care for themselves while knowing when to seek help."}, {"id": "e3188841-7bd6-4e8d-be03-4653a9a548c0", "type": "subtopic", "title": "Risk assessment and digital safety", "children": [{"id": "f12c18de-923e-4941-979d-51c22c9fc538", "type": "concept", "title": "Travel advisories, local laws, scams, nightlife, and transport safety"}, {"id": "ed53f27a-bc97-4e0